<?php

namespace App\Services;

use App\Enums\FolioStatus;
use App\Enums\TransactionType;
use App\Models\BookingAddon;
use App\Models\ChargeCode;
use App\Models\Folio;
use App\Models\OutletBill;
use App\Models\Payment;
use App\Models\SubBooking;
use App\Models\SubFolio;
use App\Models\Transaction;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\DB;
use InvalidArgumentException;

/**
 * Posts ledger entries. A charge generated by a room lands in the window its
 * routing rules point to, or else in the room's own default window. Each entry is
 * journalled in the general ledger in the same database transaction.
 */
class Ledger
{
    public function __construct(private GeneralLedger $generalLedger) {}

    public const DEFAULT_WINDOW_NAME = 'Window A';

    /** Windows per folio, lettered A to Z. */
    public const MAX_WINDOWS = 26;

    /**
     * The owner's first folio with its default window, created when missing. A booking's or
     * room's first folio stays its default when settled or locked (posting reopens it); an
     * outlet bill only reuses an open one.
     */
    public function defaultWindowFor(Model $owner, ?string $currency = null): SubFolio
    {
        return DB::transaction(function () use ($owner, $currency): SubFolio {
            $folio = Folio::query()
                ->whereMorphedTo('owner', $owner)
                ->when($owner instanceof OutletBill, fn ($query) => $query->where('status', FolioStatus::Open))
                ->oldest('id')
                ->lockForUpdate()
                ->first()
                ?? Folio::create([
                    'owner_type' => $owner->getMorphClass(),
                    'owner_id' => $owner->getKey(),
                    'status' => FolioStatus::Open,
                    'currency' => $currency ?? 'INR',
                ]);

            return $folio->subFolios()->firstOrCreate(['window_number' => 1], ['window_name' => self::DEFAULT_WINDOW_NAME]);
        });
    }

    /**
     * Opens another folio for the owner (e.g. a second bill on a booking, settled by a
     * different payer), with its first window. The first folio stays the default one.
     */
    public function openFolio(Model $owner, ?string $currency = null, ?string $windowName = null, ?Model $payer = null): SubFolio
    {
        return DB::transaction(function () use ($owner, $currency, $windowName, $payer): SubFolio {
            $folio = Folio::create([
                'owner_type' => $owner->getMorphClass(),
                'owner_id' => $owner->getKey(),
                'status' => FolioStatus::Open,
                'currency' => $currency ?? 'INR',
            ]);

            return $folio->subFolios()->create([
                'window_number' => 1,
                'window_name' => filled($windowName) ? $windowName : self::DEFAULT_WINDOW_NAME,
                'payer_type' => $payer?->getMorphClass(),
                'payer_id' => $payer?->getKey(),
            ]);
        });
    }

    /**
     * Adds the next billing window to an open folio ("Window B", "Window C", …).
     */
    public function addWindow(Folio $folio, ?string $windowName = null, ?Model $payer = null): SubFolio
    {
        return DB::transaction(function () use ($folio, $windowName, $payer): SubFolio {
            $folio = Folio::query()->lockForUpdate()->findOrFail($folio->id);
            $this->ensureWritable($folio);

            $number = (int) $folio->subFolios()->max('window_number') + 1;

            if ($number > self::MAX_WINDOWS) {
                throw new InvalidArgumentException('A folio can have at most '.self::MAX_WINDOWS.' windows.');
            }

            return $folio->subFolios()->create([
                'window_number' => $number,
                'window_name' => filled($windowName) ? $windowName : 'Window '.chr(64 + $number),
                'payer_type' => $payer?->getMorphClass(),
                'payer_id' => $payer?->getKey(),
            ]);
        });
    }

    /**
     * Posts a charge generated by a room, applying its routing rules. A rule for the
     * exact category wins over an "all charges" rule.
     */
    public function postCharge(SubBooking $source, ChargeCode $chargeCode, float $amount, ?string $description = null, ?OutletBill $outletBill = null): Transaction
    {
        $this->assertPositive($amount);

        $rule = $source->routingRules()->with('targetSubFolio')->get()
            ->filter(fn ($rule): bool => $rule->appliesTo($chargeCode->category))
            ->sortBy(fn ($rule): int => $rule->charge_category === $chargeCode->category ? 0 : 1)
            ->first();

        $window = $rule?->targetSubFolio ?? $this->defaultWindowFor($source);

        return $this->postEntry($window, TransactionType::Debit, $amount, $chargeCode, $description, $source, null, $outletBill);
    }

    /**
     * Records money received against a window.
     */
    public function postPayment(SubFolio $window, ChargeCode $chargeCode, float $amount, ?Payment $payment = null, ?string $description = null): Transaction
    {
        $this->assertPositive($amount);

        return $this->postEntry($window, TransactionType::Credit, $amount, $chargeCode, $description, null, $payment);
    }

    /**
     * A settled or locked booking folio reopens for a new entry (see FolioSettlements); a
     * settled outlet bill's folio takes nothing more.
     *
     * @throws InvalidArgumentException when the folio can't take entries
     */
    private function ensureWritable(Folio $folio): void
    {
        if ($folio->status === FolioStatus::Open) {
            return;
        }

        // Another instance may have reopened it already.
        $folio->refresh();

        if ($folio->status === FolioStatus::Open) {
            return;
        }

        if ($folio->owner_type === (new OutletBill)->getMorphClass()) {
            throw new InvalidArgumentException("Folio {$folio->id} is {$folio->status->value}; nothing can be posted to it.");
        }

        app(FolioSettlements::class)->reopen($folio);
    }

    /**
     * Posts one entry straight to a window (no routing). Amount must be positive.
     */
    public function postEntry(SubFolio $window, TransactionType $type, float $amount, ChargeCode $chargeCode, ?string $description = null, ?SubBooking $source = null, ?Payment $payment = null, ?OutletBill $outletBill = null, ?BookingAddon $bookingAddon = null): Transaction
    {
        $this->assertPositive($amount);
        $this->ensureWritable($window->folio);

        return DB::transaction(function () use ($window, $type, $amount, $chargeCode, $description, $source, $payment, $outletBill, $bookingAddon): Transaction {
            $transaction = $window->transactions()->create([
                'transaction_type' => $type,
                'amount' => round($amount, 2),
                'charge_code_id' => $chargeCode->id,
                'source_sub_booking_id' => $source?->id,
                'payment_id' => $payment?->id,
                'outlet_bill_id' => $outletBill?->id,
                'booking_addon_id' => $bookingAddon?->id,
                'description' => $description,
                'posted_at' => now(),
            ]);

            $this->generalLedger->journalTransaction($transaction->setRelation('subFolio', $window)->setRelation('chargeCode', $chargeCode)->setRelation('payment', $payment));

            return $transaction;
        });
    }

    private function assertPositive(float $amount): void
    {
        if ($amount <= 0) {
            throw new InvalidArgumentException('Ledger amounts must be positive; use a credit to reduce a balance.');
        }
    }
}
